import { type RoomState, type Room } from "matrix-js-sdk";
/**
 * A React hook for values computed from room state.
 * @param room The room.
 * @param f A mapping from the current room state to the computed value.
 * @returns The computed value.
 */
export declare function useRoomState<T>(room: Room, f: (state: RoomState) => T): T;
